{ pkgs, lib, toolbox, toolboxLib }:

let
  inherit (toolboxLib.readData ./data.json) meta versions;

  # OpenSpec is a pure-ESM TypeScript CLI published to npm. The published tarball
  # already ships the compiled `dist/` and a thin `bin/openspec.js` entrypoint, so
  # there is nothing to build — we only need runtime dependencies. All deps are
  # pure JS (no native addons), so node_modules is platform-independent: a single
  # fixed-output derivation resolves them from the package.json and one hash covers
  # every system. The main derivation lays out lib/openspec/{bin,dist,node_modules}
  # and wraps `node bin/openspec.js`.
  builders = {
    default = version: versionData:
      let
        src = pkgs.fetchurl {
          url = "https://registry.npmjs.org/@fission-ai/openspec/-/openspec-${version}.tgz";
          hash = versionData.sha256;
        };

        nodeModules = pkgs.stdenvNoCC.mkDerivation {
          pname = "openspec-node-modules";
          inherit version src;

          sourceRoot = "package";

          impureEnvVars = pkgs.lib.fetchers.proxyImpureEnvVars ++ [
            "GIT_PROXY_COMMAND"
            "SOCKS_SERVER"
          ];

          nativeBuildInputs = [ pkgs.nodejs ];
          dontConfigure = true;

          buildPhase = ''
            export HOME=$(mktemp -d)
            npm install \
              --omit=dev \
              --ignore-scripts \
              --no-audit \
              --no-fund \
              --no-progress
          '';

          installPhase = ''
            mkdir -p $out
            cp -R node_modules $out/
          '';

          dontFixup = true;
          outputHash = versionData.nodeModules;
          outputHashAlgo = "sha256";
          outputHashMode = "recursive";
        };
      in
      pkgs.stdenv.mkDerivation {
        pname = "openspec";
        inherit version src;

        sourceRoot = "package";

        nativeBuildInputs = [ pkgs.makeWrapper ];

        dontConfigure = true;
        dontBuild = true;

        installPhase = ''
          runHook preInstall

          mkdir -p $out/lib/openspec $out/bin
          cp -R bin dist package.json $out/lib/openspec/
          cp -R ${nodeModules}/node_modules $out/lib/openspec/

          makeWrapper ${pkgs.nodejs}/bin/node $out/bin/openspec \
            --add-flags "$out/lib/openspec/bin/openspec.js"

          runHook postInstall
        '';

        dontStrip = true;

        meta = with lib; {
          description = "AI-native system for spec-driven development";
          homepage = "https://github.com/Fission-AI/OpenSpec";
          license = licenses.mit;
          mainProgram = "openspec";
          platforms = [ "x86_64-linux" "aarch64-linux" "x86_64-darwin" "aarch64-darwin" ];
        };
      };
  };
in
{
  versions = toolboxLib.buildVersions "openspec" builders versions;
  default = meta.default;
}

